/**
 * Test-only: a fixed board and the JSON the status model and push snapshot
 * built from it before the drive-health module (#727). `baselineOutput`
 * uses only what existed on main, so server/fixtures/status-baseline-main.json
 * was generated by running it in a checkout of main; the drive tests compare
 * today's output, with the module off or absent, against that file.
 */
import { buildSnapshot } from '../push/snapshot.js';
import { buildStatus } from '../status/model.js';
import { DEFAULT_THRESHOLDS } from '../status/thresholds.js';
import { card, inputs, monitored, node, NOW, CYCLE_MS } from './statusFixtures.js';

/** The board's inputs for cycle `i` (0-3): one hot node, one dark, a service down, a UPS on mains. */
export function baselineInputs(i, extra = {}) {
  const hot = i >= 1 ? { cpu: '95.0', diskPercent: '91.0', temp: '82.0' } : {};
  return inputs({
    nodes: {
      n1: node(hot, { display_name: 'Hot' }),
      n2: node({}, { display_name: 'Quiet', services: [monitored('n2:web', i >= 2 ? 'down' : 'up')] }),
      n3: node({}, { display_name: 'Plain', services: [card('n3:db')] }),
    },
    ...extra,
  });
}

/** Four cycles of the board: `{ status, snapshot }` of each, as JSON-ready values. */
export function baselineOutput(extra = {}) {
  let memory = null;
  let prev = null;
  return [0, 1, 2, 3].map((i) => {
    const built = buildStatus({
      inputs: baselineInputs(i, extra),
      thresholds: DEFAULT_THRESHOLDS,
      memory,
      now: NOW + i * CYCLE_MS,
    });
    memory = built.memory;
    const caches = {
      getCached: (key) => (key === 'services' ? baselineInputs(i, extra).services : null),
      getCachedInternal: () => null,
      getAllCronStatuses: () => [],
    };
    prev = buildSnapshot(caches, prev, built.status);
    return { status: built.status, snapshot: prev };
  });
}
